responses.663ffff289202a3bd73aa4d4907727788fb02c32:
{
  "assertions": [
    {
      "statement": "HTTPX supports streaming responses for large downloads to avoid loading the entire response body into memory at once.",
      "relation": "supports",
      "quote": "For large downloads you may want to use streaming responses that do not load the entire response body into memory at once."
    },
    {
      "statement": "HTTPX can stream the binary content of a response using the iter_bytes() method.",
      "relation": "supports",
      "quote": ">>> with httpx.stream(\"GET\", \"https://www.example.com\") as r:\n...     for data in r.iter_bytes():\n...         print(data)"
    },
    {
      "statement": "HTTPX can stream the text of a response using the iter_text() method.",
      "relation": "supports",
      "quote": ">>> with httpx.stream(\"GET\", \"https://www.example.com\") as r:\n...     for text in r.iter_text():\n...         print(text)"
    },
    {
      "statement": "HTTPX can stream text line-by-line using the iter_lines() method.",
      "relation": "supports",
      "quote": ">>> with httpx.stream(\"GET\", \"https://www.example.com\") as r:\n...     for line in r.iter_lines():\n...         print(line)"
    },
    {
      "statement": "HTTPX normalizes line endings to '\\n' when streaming text.",
      "relation": "supports",
      "quote": "HTTPX will use universal line endings, normalising all cases to `\\n`."
    },
    {
      "statement": "HTTPX can access raw bytes without automatic content decoding using iter_raw().",
      "relation": "supports",
      "quote": ">>> with httpx.stream(\"GET\", \"https://www.example.com\") as r:\n...     for chunk in r.iter_raw():\n...         print(chunk)"
    },
    {
      "statement": "When using streaming responses, the response.content and response.text attributes are not available and will raise errors if accessed.",
      "relation": "supports",
      "quote": "If you're using streaming responses in any of these ways then the `response.content` and `response.text` attributes will not be available, and will raise errors if accessed."
    },
    {
      "statement": "HTTPX allows conditional loading of the response body in streaming mode by calling r.read().",
      "relation": "supports",
      "quote": ">>> with httpx.stream(\"GET\", \"https://www.example.com\") as r:\n...     if int(r.headers['Content-Length']) < TOO_LONG:\n...         r.read()\n...         print(r.text)"
    }
  ]
}

